{"title": "Slowest panels", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Slowest panels (average render time)",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "dashboard-health-monitor*",
      "body": {
        "size": 0,
        "aggs": {
          "panels": {
            "nested": {
              "path": "panels"
            },
            "aggs": {
              "by_panel": {
                "terms": {
                  "field": "panels.panel_id",
                  "size": 25,
                  "order": {
                    "avg_ms": "desc"
                  }
                },
                "aggs": {
                  "avg_ms": {
                    "avg": {
                      "field": "panels.render_ms"
                    }
                  },
                  "max_ms": {
                    "max": {
                      "field": "panels.render_ms"
                    }
                  },
                  "title": {
                    "terms": {
                      "field": "panels.panel_title",
                      "size": 1
                    }
                  },
                  "page": {
                    "reverse_nested": {},
                    "aggs": {
                      "dash": {
                        "terms": {
                          "field": "dashboard_title",
                          "size": 1
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.panels.by_panel.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.page.dash.buckets[0].key + ' / ' + datum.title.buckets[0].key",
      "as": "label"
    },
    {
      "calculate": "datum.avg_ms.value",
      "as": "avg"
    },
    {
      "calculate": "datum.max_ms.value",
      "as": "max"
    }
  ],
  "mark": {
    "type": "bar",
    "color": "#6092C0"
  },
  "encoding": {
    "y": {
      "field": "label",
      "type": "nominal",
      "sort": "-x",
      "title": null,
      "axis": {
        "labelLimit": 320
      }
    },
    "x": {
      "field": "avg",
      "type": "quantitative",
      "title": "Average render time (ms)"
    },
    "tooltip": [
      {
        "field": "label",
        "title": "Panel"
      },
      {
        "field": "avg",
        "title": "Average (ms)",
        "format": ",.0f"
      },
      {
        "field": "max",
        "title": "Slowest (ms)",
        "format": ",.0f"
      },
      {
        "field": "doc_count",
        "title": "Samples"
      }
    ]
  }
}"}}

{"title": "Panel health by dashboard", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Panel health by dashboard (share of panel results)",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "dashboard-health-monitor*",
      "body": {
        "size": 0,
        "aggs": {
          "by_dash": {
            "terms": {
              "field": "dashboard_title",
              "size": 100,
              "order": {
                "_key": "asc"
              }
            },
            "aggs": {
              "ok": {
                "nested": {
                  "path": "panels"
                },
                "aggs": {
                  "f": {
                    "filter": {
                      "term": {
                        "panels.render_status": "ok"
                      }
                    }
                  }
                }
              },
              "empty": {
                "nested": {
                  "path": "panels"
                },
                "aggs": {
                  "f": {
                    "filter": {
                      "term": {
                        "panels.render_status": "empty"
                      }
                    }
                  }
                }
              },
              "error": {
                "nested": {
                  "path": "panels"
                },
                "aggs": {
                  "f": {
                    "filter": {
                      "term": {
                        "panels.render_status": "error"
                      }
                    }
                  }
                }
              },
              "timeout": {
                "nested": {
                  "path": "panels"
                },
                "aggs": {
                  "f": {
                    "filter": {
                      "term": {
                        "panels.render_status": "timeout"
                      }
                    }
                  }
                }
              },
              "missing": {
                "nested": {
                  "path": "panels"
                },
                "aggs": {
                  "f": {
                    "filter": {
                      "term": {
                        "panels.render_status": "missing"
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.by_dash.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.key",
      "as": "dashboard"
    },
    {
      "calculate": "datum.ok.f.doc_count",
      "as": "ok"
    },
    {
      "calculate": "datum.empty.f.doc_count",
      "as": "empty"
    },
    {
      "calculate": "datum.error.f.doc_count",
      "as": "error"
    },
    {
      "calculate": "datum.timeout.f.doc_count",
      "as": "timeout"
    },
    {
      "calculate": "datum.missing.f.doc_count",
      "as": "missing"
    },
    {
      "fold": [
        "ok",
        "empty",
        "error",
        "timeout",
        "missing"
      ],
      "as": [
        "status",
        "count"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "count",
          "as": "total"
        }
      ],
      "groupby": [
        "dashboard"
      ]
    },
    {
      "calculate": "datum.total > 0 ? datum.count / datum.total : 0",
      "as": "share"
    }
  ],
  "encoding": {
    "x": {
      "field": "status",
      "type": "ordinal",
      "sort": [
        "ok",
        "empty",
        "error",
        "timeout",
        "missing"
      ],
      "title": null,
      "axis": {
        "orient": "top",
        "labelAngle": 0
      }
    },
    "y": {
      "field": "dashboard",
      "type": "nominal",
      "title": null,
      "axis": {
        "labelLimit": 260
      }
    }
  },
  "layer": [
    {
      "mark": "rect",
      "encoding": {
        "color": {
          "field": "share",
          "type": "quantitative",
          "title": "Share",
          "scale": {
            "domain": [
              0,
              1
            ],
            "scheme": "yellowgreenblue"
          }
        },
        "tooltip": [
          {
            "field": "dashboard"
          },
          {
            "field": "status"
          },
          {
            "field": "count",
            "title": "Panel results"
          },
          {
            "field": "share",
            "format": ".1%"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "fontSize": 10
      },
      "encoding": {
        "text": {
          "field": "share",
          "type": "quantitative",
          "format": ".0%"
        },
        "color": {
          "condition": {
            "test": "datum.share > 0.6",
            "value": "white"
          },
          "value": "black"
        }
      }
    }
  ]
}"}}
